inline QIcon symbol(int command,bool folder,bool dark) {
    QPixmap bitmap(64,64);bitmap.fill(Qt::transparent);QPainter p(&bitmap);p.setRenderHint(QPainter::Antialiasing);p.scale(2,2);p.setPen(QPen(QColor(dark?"#b5d8c7":"#467b65"),1.65,Qt::SolidLine,Qt::RoundCap,Qt::RoundJoin));
    if(folder){p.drawRoundedRect(QRectF(3,9,26,19),3,3);p.drawPolyline(QPolygonF{{3,11},{3,6},{12,6},{15,9}});}
    else if(command==701){for(auto point:{QPoint(5,5),QPoint(27,5),QPoint(5,27),QPoint(27,27)}){p.drawLine(point,point+QPoint(point.x()==5?6:-6,0));p.drawLine(point,point+QPoint(0,point.y()==5?6:-6));}p.drawEllipse(QRectF(12,12,8,8));}
    else if(command==712){p.drawRoundedRect(QRectF(3,5,26,19),3,3);p.drawEllipse(QRectF(12,10,8,8));p.drawLine(11,28,21,28);}
    else if(command==710){p.drawRoundedRect(QRectF(3,5,26,22),3,3);p.drawPolygon(QPolygonF{{13,10},{22,16},{13,22}});}
    else if(command==707){p.drawRoundedRect(QRectF(7,6,20,23),3,3);p.drawRoundedRect(QRectF(12,3,10,6),2,2);p.drawLine(12,15,22,15);p.drawLine(12,21,20,21);}
    else if(command==705){p.drawRoundedRect(QRectF(5,4,23,24),3,3);p.drawLine(11,11,22,11);p.drawLine(11,17,22,17);p.drawLine(11,23,17,23);}
    else if(command==708){p.drawRoundedRect(QRectF(4,4,24,24),3,3);p.drawLine(4,12,28,12);p.drawLine(12,12,12,28);}
    else if(command==709){p.drawEllipse(QRectF(4,4,24,24));p.drawLine(16,9,16,16);p.drawLine(16,16,22,19);}
    else if(command==-1){p.drawRoundedRect(QRectF(6,3,20,26),3,3);p.drawLine(10,10,22,10);for(int x:{11,21})for(int y:{16,23})p.drawPoint(x,y);}
    else {for(int x:{5,18})for(int y:{5,18})p.drawRoundedRect(QRectF(x,y,9,9),2,2);}
    p.end();bitmap.setDevicePixelRatio(2);return QIcon(bitmap);
}
